INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES
('225eba88-642a-5cb1-96c9-5d24454f2bef', 'b4a8089d-e4cc-5e47-af43-c2ee6f762bf2', 'tr', $h$Airless boya makinası nedir?$h$, $h$<div> <p>Airless boya makinası, boyayı yüksek basınçla püskürterek yüzeye eşit ve hızlı kaplama sağlayan profesyonel boya ekipmanıdır.</p> </div>$h$),
('f654fc9b-e44d-5a62-a341-c10941f904b2', 'e57b0faa-0b4b-52b3-b637-e0d87b8b1060', 'tr', $h$“Airless” ne anlama gelir?$h$, $h$<div> <p>Airless, havasız anlamına gelir ve boya püskürtmek için sıkıştırılmış hava kullanılmadığını ifade eder; bu sayede boya daha yüksek basınçla atomize edilir.</p> </div>$h$),
('79a22aa6-b3ad-5979-8a4b-d78c92611621', '39a0f646-b3a2-5a69-a6a0-23a626c3e12e', 'tr', $h$Airless makineler nerelerde kullanılır?$h$, $h$<div> <p>Geniş yüzey boyama, endüstriyel boyama, marin ve gemi yüzeyleri, zemin uygulamaları gibi birçok alanda kullanılır. </p> </div>$h$),
('7bf9a6a4-7426-5130-bfbc-9cc17a7e65d5', 'ff1ea760-0944-5b28-8eda-290ce61e4f00', 'tr', $h$Avantajları nelerdir?$h$, $h$<div> <p>Airless makineler hızlı kaplama, yüksek verim, düşük boya israfı ve eşit yüzey kaplama avantajları sunar.</p> </div>$h$),
